//! The TLS contract of the protocol-v3 gateway.
//!
//! The material under `tests/fixtures/pgsql-tls` is test-only and generated by
//! the sibling `generate.ps1`: a local CA plus a `localhost` / `127.0.0.1` leaf.
//! The cases below drive a real socket through `SSLRequest` → `S` → `rustls`
//! handshake → `StartupMessage` → `SELECT 1` → `Terminate`, so the encrypted
//! path is proven end to end instead of only negotiated.

use std::{
    collections::HashMap,
    io::{Read, Write},
    net::{TcpListener, TcpStream},
    sync::Arc,
    thread,
    time::Duration,
};

use base64::Engine as _;
use database_cluster::topology::ShardMap;
use database_execution::{cluster::LocalExecutor, pgsql::PgsqlSqlRuntime};
use database_execution::sql_schema::SqlSchemaRegistry;
use database_server::yyds::pgsql::{PgAuthentication, PgTls, TlsError, connection::serve_connection_with_auth_and_tls};
use database_storage::cluster_kv::MemoryShard;
use database_types::cluster::{ShardEpoch, ShardId};
use rustls::pki_types::{CertificateDer, ServerName};

const SSL_REQUEST: [u8; 8] = [0, 0, 0, 8, 0x04, 0xD2, 0x16, 0x2F];
const PROTOCOL_V3: u32 = 196_608;

fn fixture(name: &str) -> String {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("tests").join("fixtures").join("pgsql-tls").join(name);
    std::fs::read_to_string(&path).unwrap_or_else(|error| panic!("read `{}`: {error}", path.display()))
}

fn fixtures() -> (String, String, String) {
    (fixture("ca.pem"), fixture("server.pem"), fixture("server.key"))
}

fn certificate_der(pem: &str) -> Vec<u8> {
    let body: String = pem.lines().filter(|line| !line.starts_with("-----")).collect();
    base64::engine::general_purpose::STANDARD.decode(body).expect("the fixture certificate is base64 PEM")
}

fn runtime() -> Arc<PgsqlSqlRuntime> {
    let shard = ShardId("local-0".into());
    let executor = LocalExecutor::new(
        ShardMap::new(ShardEpoch(1), vec![shard.clone()]).unwrap(),
        HashMap::from([(shard, MemoryShard::new())]),
        Vec::new(),
    )
    .unwrap();
    Arc::new(PgsqlSqlRuntime::new(Arc::new(SqlSchemaRegistry::new_in_memory()), Arc::new(executor)))
}

fn startup_message(user: &str, database: &str) -> Vec<u8> {
    let mut payload = Vec::new();
    payload.extend_from_slice(&PROTOCOL_V3.to_be_bytes());
    for (key, value) in [("user", user), ("database", database)] {
        payload.extend_from_slice(key.as_bytes());
        payload.push(0);
        payload.extend_from_slice(value.as_bytes());
        payload.push(0);
    }
    payload.push(0);
    let mut frame = Vec::with_capacity(payload.len() + 4);
    frame.extend_from_slice(&((payload.len() + 4) as u32).to_be_bytes());
    frame.extend_from_slice(&payload);
    frame
}

fn query_frame(sql: &str) -> Vec<u8> {
    let payload = format!("{sql}\0");
    let mut frame = Vec::with_capacity(payload.len() + 5);
    frame.push(b'Q');
    frame.extend_from_slice(&((payload.len() + 4) as u32).to_be_bytes());
    frame.extend_from_slice(payload.as_bytes());
    frame
}

fn read_frame(stream: &mut (impl Read + Write)) -> (u8, Vec<u8>) {
    let mut header = [0u8; 5];
    stream.read_exact(&mut header).expect("a complete backend frame header");
    let length = u32::from_be_bytes([header[1], header[2], header[3], header[4]]) as usize;
    assert!(length >= 4, "a frame length includes its own four bytes");
    let mut payload = vec![0u8; length - 4];
    stream.read_exact(&mut payload).expect("a complete backend frame payload");
    (header[0], payload)
}

fn read_until_ready(stream: &mut (impl Read + Write)) -> Vec<(u8, Vec<u8>)> {
    let mut frames = Vec::new();
    loop {
        let frame = read_frame(stream);
        let ready = frame.0 == b'Z';
        frames.push(frame);
        if ready {
            return frames;
        }
    }
}

#[test]
fn an_encrypted_session_serves_a_query_over_tls() {
    let (ca_pem, certificate_pem, key_pem) = fixtures();
    let tls = Arc::new(PgTls::from_pem(&certificate_pem, &key_pem).expect("the fixture pair loads"));
    let listener = TcpListener::bind("127.0.0.1:0").unwrap();
    let address = listener.local_addr().unwrap();
    let server = thread::spawn(move || {
        let (stream, _) = listener.accept().unwrap();
        serve_connection_with_auth_and_tls(stream, Some(runtime()), PgAuthentication::Trust, Some(tls))
    });

    let mut socket = TcpStream::connect(address).unwrap();
    socket.set_read_timeout(Some(Duration::from_secs(10))).unwrap();
    socket.write_all(&SSL_REQUEST).unwrap();
    let mut answer = [0u8; 1];
    socket.read_exact(&mut answer).unwrap();
    assert_eq!(&answer, b"S", "a listener with a certificate must accept TLS");

    let mut roots = rustls::RootCertStore::empty();
    roots.add(CertificateDer::from(certificate_der(&ca_pem))).unwrap();
    let config = rustls::ClientConfig::builder().with_root_certificates(roots).with_no_client_auth();
    let name = ServerName::try_from("localhost").unwrap();
    let connection = rustls::ClientConnection::new(Arc::new(config), name).unwrap();
    let mut tls = rustls::StreamOwned::new(connection, socket);

    tls.write_all(&startup_message("postgres", "postgres")).unwrap();
    tls.flush().unwrap();
    let frames = read_until_ready(&mut tls);
    assert_eq!(frames[0].0, b'R', "the encrypted session must reach AuthenticationOk");
    assert_eq!(frames[0].1, vec![0, 0, 0, 0], "AuthenticationOk carries the zero result");

    tls.write_all(&query_frame("SELECT 1")).unwrap();
    tls.flush().unwrap();
    let frames = read_until_ready(&mut tls);
    let tags: Vec<u8> = frames.iter().map(|frame| frame.0).collect();
    assert_eq!(tags, vec![b'T', b'D', b'C', b'Z'], "`SELECT 1` must describe, emit, complete and report ready");
    assert_eq!(frames[1].1.last(), Some(&b'1'), "the data row must carry the query result");

    tls.write_all(&[b'X', 0, 0, 0, 4]).unwrap();
    tls.flush().unwrap();
    server.join().unwrap().unwrap();
}

#[test]
fn a_plaintext_startup_is_rejected_when_the_listener_requires_tls() {
    let (_, certificate_pem, key_pem) = fixtures();
    let tls = Arc::new(PgTls::from_pem(&certificate_pem, &key_pem).unwrap().require_client_tls());
    let listener = TcpListener::bind("127.0.0.1:0").unwrap();
    let address = listener.local_addr().unwrap();
    let server = thread::spawn(move || {
        let (stream, _) = listener.accept().unwrap();
        serve_connection_with_auth_and_tls(stream, Some(runtime()), PgAuthentication::Trust, Some(tls))
    });

    let mut client = TcpStream::connect(address).unwrap();
    client.set_read_timeout(Some(Duration::from_secs(10))).unwrap();
    client.write_all(&startup_message("postgres", "postgres")).unwrap();
    let (tag, payload) = read_frame(&mut client);
    assert_eq!(tag, b'E', "a TLS-only listener must answer an error, not serve the session");
    let text = String::from_utf8_lossy(&payload);
    assert!(text.starts_with("SFATAL\0C28000\0"), "the refusal must be a fatal `28000`: {text:?}");
    assert!(text.contains("TLS is required"), "the refusal must name the missing TLS step: {text:?}");
    server.join().unwrap().unwrap();
}

#[test]
fn an_ssl_request_is_declined_when_no_certificate_is_configured() {
    let listener = TcpListener::bind("127.0.0.1:0").unwrap();
    let address = listener.local_addr().unwrap();
    let server = thread::spawn(move || {
        let (stream, _) = listener.accept().unwrap();
        let _ = serve_connection_with_auth_and_tls(stream, None, PgAuthentication::Trust, None);
    });

    let mut client = TcpStream::connect(address).unwrap();
    client.write_all(&SSL_REQUEST).unwrap();
    let mut reply = [0u8; 1];
    client.read_exact(&mut reply).unwrap();
    assert_eq!(&reply, b"N", "a listener without a certificate must decline TLS");

    // The same connection then runs a plaintext protocol-v3 startup.
    client.write_all(&startup_message("postgres", "postgres")).unwrap();
    let mut tag = [0u8; 1];
    client.read_exact(&mut tag).unwrap();
    assert_eq!(tag[0], b'R', "the startup must reach AuthenticationOk");
    client.write_all(&[b'X', 0, 0, 0, 4]).unwrap();
    server.join().unwrap();
}

#[test]
fn tls_configuration_rejects_material_it_cannot_use() {
    let (_, certificate_pem, key_pem) = fixtures();
    assert!(PgTls::from_pem(&certificate_pem, &key_pem).is_ok(), "the fixture pair must load");
    assert_eq!(
        PgTls::from_pem("not a certificate", "not a key").unwrap_err(),
        TlsError::Malformed("PEM text carries no `CERTIFICATE` block".to_string())
    );
    assert_eq!(
        PgTls::from_pem(&certificate_pem, "no key").unwrap_err(),
        TlsError::Malformed("PEM text carries no private key block".to_string())
    );
    assert_eq!(
        PgTls::from_pem("-----BEGIN CERTIFICATE-----\nZm9v\n", &key_pem).unwrap_err(),
        TlsError::Malformed("unterminated `CERTIFICATE` PEM block".to_string())
    );
    assert!(
        matches!(
            PgTls::from_pem("-----BEGIN CERTIFICATE-----\nZm9v\n-----END CERTIFICATE-----\n", &key_pem),
            Err(TlsError::Rejected(_))
        ),
        "a certificate the TLS stack cannot parse must be rejected, not silently accepted"
    );
}
